  box(29,.3,21,edge,0,-.21,-23.8);
  for(const x of [-8,8]){box(11,5.2,18,stone,x,2.6,-24);box(11.7,.24,18.7,paper,x,5.32,-24);box(7.4,.16,1.6,metal,x,5.49,-24);}
  box(5,4.65,17,stone,0,2.32,-23);box(5.7,.2,17.4,paper,0,4.76,-23);
  // One broad canopy and an open clerestory replace repetitive ceiling bars.
  box(28,.24,9,stone,0,6.4,-8.5);box(28,.24,8.3,stone,0,6.4,8.1);
  box(27.6,.055,8.7,edge,0,6.245,-8.5);box(27.6,.055,8,edge,0,6.245,8.1);
  box(5,.32,8.8,stone,-11.5,6.4,-.3);box(5,.32,8.8,stone,11.5,6.4,-.3);
