  for(const x of [-11.5,11.5])for(const z of [-9,-3.3,2.35,8])box(.22,6.24,.42,stone,x,3.12,z);
  // Deep openings and a continuous thin reveal give the pale masonry depth.
  box(.35,3.8,8.5,stone,-12,1.9,-7);box(.35,3.8,6.3,stone,12,1.9,-8);
  box(7.9,5.6,.38,stone,-8,2.8,-10);box(7.9,5.6,.38,stone,8,2.8,-10);
  box(8.2,.8,.6,stone,0,5.6,-10);box(.42,5.2,4.7,stone,-4.15,2.6,-12.1);box(.42,5.2,4.7,stone,4.15,2.6,-12.1);
  box(8.4,5.6,.3,edge,0,2.8,-14.4);box(8,.08,4.5,floor,0,.015,-12.1);
